 *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
 body {
   font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
   background: #0d1117; color: #c9d1d9; padding: 1.5rem 2rem 3rem;
   max-width: 920px; margin: 0 auto; line-height: 1.5;
 }

 /* Header */
 header {
   display: flex; align-items: center; justify-content: space-between;
   margin-bottom: 1.25rem; flex-wrap: wrap; gap: 0.75rem;
 }
 .header-left { display: flex; align-items: baseline; gap: 0.6rem; }
 .header-left h1 { font-size: 1.4rem; color: #f0f6fc; }
 .tagline { font-size: 0.8rem; color: #8b949e; }
 .btn-shutdown {
   background: none; border: 1px solid #f8514966; color: #f85149;
   font-size: 0.8rem; padding: 0.35rem 0.75rem; border-radius: 6px; cursor: pointer;
   transition: 0.15s;
 }
 .btn-shutdown:hover { background: #f851491a; border-color: #f85149; }

 /* Buttons */
 .btn-primary {
   background: #238636; border: 1px solid #2ea043; color: #fff;
   font-size: 0.85rem; padding: 0.4rem 0.9rem; border-radius: 6px; cursor: pointer;
 }
 .btn-primary:hover { background: #2ea043; }
 .btn {
   background: #21262d; border: 1px solid #30363d; color: #c9d1d9;
   font-size: 0.85rem; padding: 0.4rem 0.9rem; border-radius: 6px; cursor: pointer;
 }
 .btn:hover { background: #30363d; }
 .btn-danger {
   background: none; border: none; color: #f85149; cursor: pointer;
   font-size: 0.85rem; padding: 0.15rem 0.3rem; border-radius: 4px;
 }
 .btn-danger:hover { background: #f851491a; }

 /* Panel */
 .panel {
   background: #161b22; border: 1px dashed #30363d; border-radius: 8px;
   padding: 1rem 1.25rem; margin-bottom: 1rem;
 }
 .panel.hidden { display: none; }
 .panel h3 { font-size: 0.9rem; margin-bottom: 0.6rem; color: #f0f6fc; }
 .form-row { display: flex; gap: 0.5rem; margin-bottom: 0.5rem; flex-wrap: wrap; }
 .form-row input { flex: 1; min-width: 160px; }
 .form-actions { display: flex; gap: 0.5rem; }

 /* Inputs */
 input, select {
   background: #21262d; border: 1px solid #30363d; color: #c9d1d9;
   border-radius: 6px; padding: 0.4rem 0.6rem; font-size: 0.85rem;
   font-family: inherit;
 }
 input:focus, select:focus { outline: none; border-color: #58a6ff; }

 /* Project Card */
 .project {
   background: #161b22; border: 1px solid #30363d; border-radius: 8px;
   padding: 0.9rem 1.25rem; margin-bottom: 0.85rem;
   transition: opacity 0.2s;
 }
 .project-header {
   display: flex; align-items: center; gap: 0.5rem; cursor: pointer;
   user-select: none;
 }
 .project-header .collapse-btn {
   background: none; border: none; color: #8b949e; cursor: pointer;
   font-size: 0.75rem; padding: 0.1rem 0.2rem; width: 1.2rem; text-align: center;
   flex-shrink: 0;
 }
 .project-header .collapse-btn:hover { color: #c9d1d9; }
 .project-name {
   font-weight: 600; color: #58a6ff; font-size: 0.95rem;
   cursor: text; flex-shrink: 0; max-width: 240px;
   overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
 }
 .project-url {
   font-size: 0.72rem; color: #8b949e; margin-left: 1.7rem;
   font-family: 'SF Mono', 'Cascadia Code', monospace;
   cursor: text; word-break: break-all; white-space: nowrap;
   overflow: hidden; text-overflow: ellipsis;
 }
 .project-url a { color: #8b949e; text-decoration: none; }
 .project-url a:hover { color: #58a6ff; text-decoration: underline; }

 /* Status badge */
 .status-badge {
   font-size: 0.65rem; padding: 0.1rem 0.45rem; border-radius: 10px;
   font-weight: 500; text-transform: uppercase; letter-spacing: 0.04em;
   flex-shrink: 0;
 }
 .st-active { background: #1f6feb33; color: #58a6ff; border: 1px solid #1f6feb66; }
 .st-onhold { background: #d2992233; color: #d29922; border: 1px solid #d2992266; }
 .st-completed { background: #23863633; color: #3fb950; border: 1px solid #23863666; }
 .st-planning { background: #bc8cff33; color: #bc8cff; border: 1px solid #bc8cff66; }

 .status-select {
   margin-left: auto; font-size: 0.75rem; padding: 0.15rem 0.4rem;
   flex-shrink: 0; max-width: 100px;
 }
 .delete-project-btn {
   margin-left: 0.25rem; flex-shrink: 0;
 }

 /* Body (entries area) */
 .project-body { margin-top: 0.5rem; margin-left: 1.7rem; }
 .collapsed .project-body { display: none; }

 /* Entry date heading */
 .entry-date-heading {
   font-weight: 600; color: #f0f6fc; font-size: 0.8rem;
   margin: 0.6rem 0 0.25rem 0; padding-bottom: 0.15rem;
   border-bottom: 1px solid #21262d;
 }

 /* Entry list */
 .entry-list { list-style: none; padding: 0; }
 .entry-item {
   display: flex; align-items: center; gap: 0.4rem;
   padding: 0.25rem 0.3rem; font-size: 0.85rem; color: #c9d1d9;
   border-radius: 4px; transition: 0.15s; cursor: default;
 }
 .entry-item:hover { background: #1c2128; }
 .entry-item.dragging { opacity: 0.4; }
 .entry-item.drag-over { border-top: 2px solid #58a6ff; }
 .entry-item.done { color: #8b949e; }
 .entry-item.done .entry-text { text-decoration: line-through; }

 /* drag handle */
 .drag-handle {
   cursor: grab; color: #484f58; font-size: 0.75rem;
   flex-shrink: 0; width: 1rem; text-align: center; user-select: none;
 }
 .entry-item:hover .drag-handle { color: #8b949e; }
 .drag-handle:active { cursor: grabbing; }

 .entry-text {
   flex: 1; min-width: 0; word-break: break-word;
   padding: 0.1rem 0; cursor: text;
 }
 .entry-actions {
   display: flex; gap: 0.15rem; flex-shrink: 0; opacity: 0;
   transition: opacity 0.1s;
 }
 .entry-item:hover .entry-actions { opacity: 1; }
 .icon-btn {
   background: none; border: none; color: #8b949e; cursor: pointer;
   font-size: 0.75rem; padding: 0.1rem 0.25rem; border-radius: 3px;
 }
 .icon-btn:hover { background: #30363d; }
 .icon-btn.done-btn:hover { color: #3fb950; }
 .icon-btn.del-btn:hover { color: #f85149; }

 /* Add entry form */
 .add-entry-row {
   display: flex; gap: 0.5rem; margin-top: 0.5rem; align-items: center;
 }
 .add-entry-row input[type="date"] { font-size: 0.78rem; flex-shrink: 0; width: 130px; }
 .add-entry-row input[type="text"] { flex: 1; }
 .add-entry-row button { flex-shrink: 0; }

 /* Inline edit */
 .inline-input {
   background: transparent; border: 1px solid #58a6ff; color: #c9d1d9;
   border-radius: 4px; padding: 0.1rem 0.3rem; font-size: inherit;
   font-family: inherit; width: 100%; outline: none;
 }

+/* Toast notifications */
+#toast-container {
+  position: fixed; bottom: 1.5rem; right: 1.5rem; z-index: 200;
+  display: flex; flex-direction: column; gap: 0.5rem; pointer-events: none;
+}
+.toast {
+  background: #161b22; border: 1px solid #30363d; color: #c9d1d9;
+  padding: 0.6rem 1rem; border-radius: 6px; font-size: 0.85rem;
+  max-width: 360px; pointer-events: auto;
+  animation: toast-in 0.2s ease-out;
+}
+.toast.error { border-color: #f8514966; color: #f85149; background: #161b22; }
+.toast.success { border-color: #23863666; color: #3fb950; background: #161b22; }
+@keyframes toast-in {
+  from { opacity: 0; transform: translateY(8px); }
+  to { opacity: 1; transform: translateY(0); }
+}
+
 /* Shutdown overlay */
 #shutdownOverlay {
   position: fixed; inset: 0; background: #0d1117f0;
   display: flex; align-items: center; justify-content: center;
   z-index: 100;
 }
 #shutdownOverlay.hidden { display: none; }
 .shutdown-msg { text-align: center; }
 .shutdown-msg h2 { font-size: 1.5rem; color: #f0f6fc; margin-bottom: 0.5rem; }
 .shutdown-msg p { color: #8b949e; margin-bottom: 1rem; }

 /* Empty state */
 .empty-state { text-align: center; padding: 2.5rem 1rem; color: #8b949e; }
 .empty-state p { margin-bottom: 0.3rem; }

 /* Confirmation dialog — native confirm() is fine */

 /* New project button */
 #newProjectBtn { margin-bottom: 0.75rem; }

 /* Responsive */
 @media (max-width: 600px) {
   body { padding: 1rem; }
   .project { padding: 0.7rem 1rem; }
   .project-body { margin-left: 0; }
   .project-url { margin-left: 0; }
   .status-select { max-width: 80px; }
   .add-entry-row { flex-wrap: wrap; }
 }

