async function toggleDone(eid) {
  for (const p of projects) {
    const e = p.entries.find(entry => entry.id === eid);
    if (e) {
      const prev = e.done;
      e.done = e.done ? 0 : 1;
      try {
        await API.updateEntry(eid, { text: e.text, done: e.done });
        render();
      } catch (err) {
        e.done = prev;
        render();
        showToast(err.message);
      }
      return;
    }
  }
}

