    await API.deleteEntry(eid);
    for (const p of projects) {
      const idx = p.entries.findIndex(e => e.id === eid);
      if (idx !== -1) { p.entries.splice(idx, 1); break; }
    }
    render();
  } catch (e) { showToast(e.message); }
}

